static reloc_howto_type adl_elf_howto_table[] = {
  HOWTO(258,0,2,32,0,0,complain_overflow_unsigned,bfd_elf_generic_reloc,(char*)"R_AARCH64_ABS32",0,0x0,0xffffffff,0), // relocation R_AARCH64_ABS32 (R_AARCH64_ABS32)
  HOWTO(257,0,4,64,0,0,complain_overflow_unsigned,bfd_elf_generic_reloc,(char*)"R_AARCH64_ABS64",0,0x0,0xffffffffffffffff,0), // relocation R_AARCH64_ABS64 (R_AARCH64_ABS64)
  HOWTO(261,0,2,32,1,0,complain_overflow_dont,bfd_elf_generic_reloc,(char*)"R_AARCH64_PREL32",0,0x0,0xffffffff,1), // relocation R_AARCH64_PREL32 (R_AARCH64_PREL32)
  HOWTO(2,0,2,32,0,0,complain_overflow_unsigned,bfd_elf_generic_reloc,(char*)"R_ARM_ABS32",0,0x0,0xffffffff,0), // relocation R_ARM_ABS32 (R_ARM_ABS32)
  HOWTO(55,0,2,32,0,0,complain_overflow_unsigned,bfd_elf_generic_reloc,(char*)"R_ARM_ABS32_NOI",0,0x0,0xffffffff,0), // relocation R_ARM_ABS32_NOI (R_ARM_ABS32_NOI)
  HOWTO(56,0,2,32,1,0,complain_overflow_dont,bfd_elf_generic_reloc,(char*)"R_ARM_REL32_NOI",0,0x0,0xffffffff,1), // relocation R_ARM_REL32_NOI (R_ARM_REL32_NOI)
  EMPTY_HOWTO(-1)
};

static unsigned num_adl_elf_howtos ATTRIBUTE_UNUSED = 7;

extern "C" reloc_howto_type *adl_get_howto_array(unsigned *num_howtos)
{
  *num_howtos = 6;
  return adl_elf_howto_table;
}


extern "C" reloc_howto_type *adl_elf_type_to_howto(unsigned r)
{
  switch (r) {
    case 258:
    return &adl_elf_howto_table[0];
    case 257:
    return &adl_elf_howto_table[1];
    case 261:
    return &adl_elf_howto_table[2];
    case 2:
    return &adl_elf_howto_table[3];
    case 55:
    return &adl_elf_howto_table[4];
    case 56:
    return &adl_elf_howto_table[5];
  }
  return 0;
}


extern "C" reloc_howto_type *adl_bfd_code_to_howto(bfd_reloc_code_real_type code)
{
  switch (code) {
    case (BFD_RELOC_UNUSED + 4):
    return &adl_elf_howto_table[5];
    case (BFD_RELOC_UNUSED + 3):
    return &adl_elf_howto_table[4];
    case (BFD_RELOC_UNUSED + 2):
    return &adl_elf_howto_table[2];
    case (BFD_RELOC_UNUSED + 1):
    return &adl_elf_howto_table[0];
    case 1:
    return &adl_elf_howto_table[1];
    case 2:
    return &adl_elf_howto_table[3];
    default:
    return 0;
  }
}


static std::unordered_map<addr_t,addr_t> relocation_hash;

static inline void set_relocation_value(addr_t key,addr_t value)
{
  relocation_hash[key] = value;
}

addr_t get_relocation_value(addr_t key)
{
  return relocation_hash[key];
}

bool get_relocation_value(addr_t &value,addr_t key)
{
  auto i = relocation_hash.find(key);
  if (i != relocation_hash.end()) {
    value = i->second;
    return true;
  } else {
    return false;
  }
}

typedef void (*reloc_setter)(unsigned *,unsigned,int,bfd_uint64_t);
typedef bfd_uint64_t (*reloc_action)(bfd_uint64_t,bfd_uint64_t,int);

static void R_AARCH64_ABS32_set (unsigned *data,unsigned size,int big_endian,bfd_uint64_t addr)
{
  Disassembler_adl::clear_sysram_mem_start_addr_width_128(data);
  Disassembler_adl::set_sysram_mem_start_addr_width_128(data,addr);
}

static void R_AARCH64_PREL32_set (unsigned *data,unsigned size,int big_endian,bfd_uint64_t addr)
{
  Disassembler_adl::clear_jmp_addr_width_128(data);
  Disassembler_adl::set_jmp_addr_width_128(data,addr);
}

static void R_ARM_ABS32_NOI_set (unsigned *data,unsigned size,int big_endian,bfd_uint64_t addr)
{
  Disassembler_adl::clear_sysram_mem_start_addr_width_128(data);
  Disassembler_adl::set_sysram_mem_start_addr_width_128(data,addr);
}

static void R_ARM_REL32_NOI_set (unsigned *data,unsigned size,int big_endian,bfd_uint64_t addr)
{
  Disassembler_adl::clear_jmp_addr_width_128(data);
  Disassembler_adl::set_jmp_addr_width_128(data,addr);
}

extern "C" void adl_get_reloc_funcs(unsigned type,reloc_setter *rs,reloc_action *ra,int *size,int *inner_size,int *offset)
{
  switch (type) {
    case 258:
    *rs = R_AARCH64_ABS32_set;
    *size = 16;
    *inner_size = 0;
    *offset = 8;
    break;
    case 257:
    break;
    case 261:
    *rs = R_AARCH64_PREL32_set;
    *size = 16;
    *inner_size = 0;
    *offset = 4;
    break;
    case 2:
    break;
    case 55:
    *rs = R_ARM_ABS32_NOI_set;
    *size = 16;
    *inner_size = 0;
    *offset = 8;
    break;
    case 56:
    *rs = R_ARM_REL32_NOI_set;
    *size = 16;
    *inner_size = 0;
    *offset = 4;
    break;
  }
}

